/**
 * Reports — CSV / PDF exports generated by the Flask API from Hive analytics.
 * Never generated in the browser and never filled with sample data.
 */
import { icon } from "../components/icons.js";
import { createDataTable } from "../components/dataTable.js";
import { setButtonLoading } from "../components/modal.js";
import { errorState, loadingState } from "../components/states.js";
import { toast } from "../components/toast.js";
import { callout, card, pageHeader, selectOptions } from "../components/ui.js";
import { listBatches } from "../services/batches.js";
import { listFarms } from "../services/farms.js";
import { downloadReport, listReports, REPORT_TYPES } from "../services/reports.js";
import { downloadFile } from "../utils/csv.js";
import { $, html, on, setHtml } from "../utils/dom.js";
import { formatBytes, formatDate, formatDateTime, formatRelative, toIsoDate } from "../utils/format.js";
import { setFieldError } from "../utils/validation.js";
import "../styles/pages/reports.css";

function defaultRange() {
  const to = new Date();
  const from = new Date();
  from.setDate(from.getDate() - 29);
  return { from: toIsoDate(from), to: toIsoDate(to) };
}

const typeLabel = (id) => REPORT_TYPES.find((t) => t.id === id)?.label || id;

export default {
  title: "Reports",
  async render(root, ctx) {
    const range = defaultRange();
    const state = { farms: [], batches: [] };

    setHtml(
      root,
      html`${pageHeader({
          title: "Reports",
          subtitle: "Export farm performance, environmental, feed, growth, mortality and prediction reports as CSV or PDF.",
        })}
        ${card({
          title: "Report filters",
          icon: "filter",
          className: "pa-section",
          body: html`<form class="pa-report-filters" data-filters novalidate>
              <div class="pa-field">
                <label class="form-label" for="rep-from">From</label>
                <input type="date" class="form-control" id="rep-from" name="from" value="${range.from}" max="${range.to}" />
              </div>
              <div class="pa-field">
                <label class="form-label" for="rep-to">To</label>
                <input type="date" class="form-control" id="rep-to" name="to" value="${range.to}" />
              </div>
              <div class="pa-field">
                <label class="form-label" for="rep-farm">Farm</label>
                <select class="form-select" id="rep-farm" name="farm"><option value="">All farms</option></select>
              </div>
              <div class="pa-field">
                <label class="form-label" for="rep-batch">Batch</label>
                <select class="form-select" id="rep-batch" name="batch"><option value="">All batches</option></select>
              </div>
              <div class="pa-report-filters__actions">
                <button type="button" class="btn btn-ghost" data-action="reset">Reset</button>
              </div>
            </form>
            <div class="pa-text-xs pa-text-2 mt-2" data-filter-summary></div>`,
        })}
        <section class="pa-section" aria-labelledby="rep-types">
          <div class="pa-section-head"><h2 class="pa-section-title" id="rep-types">Available reports</h2></div>
          <div class="pa-grid pa-grid--3">
            ${REPORT_TYPES.map(
              (t) => html`<article class="pa-card pa-report-card">
                <div class="pa-report-card__head">
                  <span class="pa-kpi__icon">${icon(t.icon, { size: 16 })}</span>
                  <h3 class="pa-h4">${t.label}</h3>
                </div>
                <p class="pa-report-card__desc">${t.description}</p>
                ${t.id === "predictions" ? html`<p class="pa-report-card__note">${icon("shield-alert", { size: 13 })}Predictions are estimates, not disease diagnoses.</p>` : ""}
                <div class="pa-report-card__actions">
                  <button type="button" class="btn btn-secondary btn-sm" data-export="${t.id}" data-format="csv">${icon("file-spreadsheet", { size: 14 })}CSV</button>
                  <button type="button" class="btn btn-secondary btn-sm" data-export="${t.id}" data-format="pdf">${icon("file-down", { size: 14 })}PDF</button>
                </div>
              </article>`,
            )}
          </div>
          <div class="mt-3">${callout({
            tone: "info",
            message: "Reports are generated by the server from HiveQL query results for the selected filters. Nothing is generated in the browser.",
          })}</div>
        </section>
        ${card({
          title: "Generated reports",
          icon: "history",
          actions: html`<button type="button" class="btn btn-ghost btn-sm" data-action="reload-history">${icon("refresh", { size: 14 })}Refresh</button>`,
          body: html`<div data-history>${loadingState("Loading report history…", { compact: true })}</div>`,
          flush: true,
        })}`,
    );

    const form = $("[data-filters]", root);
    const farmSelect = form.elements.namedItem("farm");
    const batchSelect = form.elements.namedItem("batch");

    function readFilters() {
      return {
        from: form.elements.namedItem("from").value,
        to: form.elements.namedItem("to").value,
        farmId: farmSelect.value,
        batchId: batchSelect.value,
      };
    }

    function validateFilters() {
      const { from, to } = readFilters();
      let fromError = null;
      let toError = null;
      if (from && to && from > to) toError = "The end date must be on or after the start date.";
      if (!from) fromError = "Choose a start date.";
      if (!to) toError = toError || "Choose an end date.";
      setFieldError(form, "from", fromError);
      setFieldError(form, "to", toError);
      return !fromError && !toError;
    }

    function updateSummary() {
      const f = readFilters();
      const farm = state.farms.find((x) => String(x.id) === f.farmId)?.name || "All farms";
      const batch = state.batches.find((x) => String(x.id) === f.batchId)?.code || "all batches";
      $("[data-filter-summary]", root).textContent = `Reports will cover ${formatDate(f.from)} – ${formatDate(f.to)} · ${farm} · ${batch}`;
      form.elements.namedItem("from").max = f.to || "";
      form.elements.namedItem("to").min = f.from || "";
    }

    async function loadFarms() {
      try {
        const { data } = await listFarms();
        if (!ctx.isCurrent()) return;
        state.farms = data;
        setHtml(farmSelect, html`<option value="">All farms</option>${selectOptions(data.map((f) => ({ value: f.id, label: f.name })), "")}`);
      } catch {
        farmSelect.disabled = true;
        farmSelect.title = "Farm list unavailable — the API is not connected";
      }
      updateSummary();
    }

    async function loadBatches() {
      const farmId = farmSelect.value;
      batchSelect.disabled = true;
      setHtml(batchSelect, html`<option value="">All batches</option>`);
      try {
        const { data } = await listBatches({ farmId: farmId || undefined });
        if (!ctx.isCurrent()) return;
        state.batches = data;
        setHtml(batchSelect, html`<option value="">All batches</option>${selectOptions(data.map((b) => ({ value: b.id, label: `${b.code} · ${b.poultryType}` })), "")}`);
        batchSelect.disabled = false;
        batchSelect.title = "";
      } catch {
        state.batches = [];
        batchSelect.title = "Batch list unavailable — the API is not connected";
      }
      updateSummary();
    }

    async function exportReport(button) {
      if (!validateFilters()) {
        toast.warning("Check the filters", "The report date range is not valid.");
        return;
      }
      const { exportType: type, format } = { exportType: button.dataset.export, format: button.dataset.format };
      const filters = readFilters();
      setButtonLoading(button, true, "Generating…");
      try {
        const { blob, filename } = await downloadReport(type, { format, ...filters });
        if (!ctx.isCurrent()) return;
        downloadFile(blob, filename);
        toast.success("Report downloaded", `${typeLabel(type)} report (${format.toUpperCase()}) — ${filename}`);
        loadHistory();
      } catch (error) {
        if (ctx.isCurrent()) toast.apiError(error, `${typeLabel(type)} report not generated`);
      } finally {
        if (button.isConnected) setButtonLoading(button, false);
      }
    }

    let historyTable = null;
    async function loadHistory() {
      const holder = $("[data-history]", root);
      historyTable?.destroy();
      historyTable = null;
      setHtml(holder, loadingState("Loading report history…", { compact: true }));
      try {
        const { data } = await listReports({ limit: 25 });
        if (!ctx.isCurrent()) return;
        historyTable = createDataTable(holder, {
          rows: data,
          pageSize: 8,
          caption: "Generated reports",
          sortKey: "createdAt",
          sortDir: "desc",
          columns: [
            { key: "type", label: "Report", sortable: true, render: (r) => html`<span class="pa-cell-primary">${typeLabel(r.type)}</span>` },
            { key: "format", label: "Format", sortable: true, render: (r) => html`<span class="pa-badge pa-badge--neutral">${String(r.format || "").toUpperCase()}</span>` },
            {
              key: "filters",
              label: "Filters",
              render: (r) => {
                const f = r.filters || {};
                return html`<span class="pa-text-sm pa-text-2">${[f.from && f.to ? `${formatDate(f.from)} – ${formatDate(f.to)}` : null, f.farm, f.batch].filter(Boolean).join(" · ") || "—"}</span>`;
              },
            },
            { key: "sizeBytes", label: "Size", sortable: true, align: "num", render: (r) => formatBytes(r.sizeBytes) },
            { key: "generatedBy", label: "Generated by", sortable: true },
            { key: "createdAt", label: "Generated", sortable: true, render: (r) => html`<span title="${formatDateTime(r.createdAt)}">${formatRelative(r.createdAt)}</span>` },
          ],
          empty: { icon: "file-text", title: "No reports generated yet", message: "Reports you export are recorded here." },
        });
      } catch (error) {
        if (ctx.isCurrent()) setHtml(holder, errorState(error, { compact: true }));
      }
    }

    const offs = [
      on(root, "click", "[data-export]", (_e, btn) => exportReport(btn)),
      on(form, "change", "input, select", (e) => {
        if (e.target === farmSelect) loadBatches();
        if (e.target.type === "date") validateFilters();
        updateSummary();
      }),
      on(root, "click", "[data-action=reset]", () => {
        const r = defaultRange();
        form.elements.namedItem("from").value = r.from;
        form.elements.namedItem("to").value = r.to;
        farmSelect.value = "";
        validateFilters();
        loadBatches();
      }),
      on(root, "click", "[data-action=reload-history], [data-history] [data-action=retry]", loadHistory),
    ];
    form.addEventListener("submit", (e) => e.preventDefault());
    ctx.onCleanup(() => {
      offs.forEach((off) => off());
      historyTable?.destroy();
    });

    updateSummary();
    loadHistory();
    await loadFarms();
    await loadBatches();
  },
};
